-- 015: Steam user tags for the whole catalogue, and the co-op flag derived from them.
--
--   npm run db:migrate -- --file=./migrations/015-steam-tags.sql
--
-- Generated by scripts/backfill-tags.mjs --all, which reads each game's store page.
-- It replaces an earlier pass that took tags from SteamSpy: SteamSpy had none for
-- 118 of these 337 rows (the unreleased and newly released ones), and it orders the
-- same tags differently from Steam, which matters because classifyCoop's window is
-- calibrated on Steam's order. Mixing the two sources made is_coop mean two
-- different things depending on which row you looked at.
--
-- 308 of 337 classify as co-op; the 29 excluded are PvP-primary (Rainbow Six,
-- Apex, Overwatch, ARC Raiders, THE FINALS, Warzone, SMITE 2 and similar).
--
-- Idempotent: every statement is a plain UPDATE keyed on appid.

UPDATE coop_apps SET tags = '["Open World Survival Craft","Sandbox","Survival","2D","Multiplayer","Pixel Graphics","Adventure","Crafting","Building","Exploration","Co-op","Open World"]', is_coop = 1, tags_at = unixepoch() WHERE appid = 105600;
UPDATE coop_apps SET tags = '["FPS","PvP","Multiplayer","Shooter","Tactical","eSports","Competitive","Online Co-Op","Action","Hero Shooter","Team-Based","Military"]', is_coop = 0, tags_at = unixepoch() WHERE appid = 359550;
